import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_runtime.h>

// Direct 3D convolution kernel specialized for the (K, K, 1) kernel shape:
// a square KxK convolution over spatial dims 2 and 3, with a pointwise
// (kernel-size-1) extent over the last (depth) dim. groups == 1.
// Input  layout: (N, IC, H, W, D)   contiguous
// Weight layout: (OC, IC, K, K, 1)  contiguous
// Output layout: (N, OC, HO, WO, DO) contiguous
template <int K>
__global__ void conv3d_kk1_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N, int IC, int H, int W, int D,
    int OC, int HO, int WO, int DO,
    int sh, int sw, int sd,
    int ph, int pw, int pd,
    int dh, int dw,
    bool has_bias)
{
    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long total = (long long)N * OC * HO * WO * DO;
    if (idx >= total) return;

    // Decode linear output index; depth is innermost so consecutive
    // threads access consecutive memory (coalesced loads/stores).
    int do_ = idx % DO;
    long long t = idx / DO;
    int wo = t % WO; t /= WO;
    int ho = t % HO; t /= HO;
    int oc = t % OC;
    int n  = (int)(t / OC);

    float sum = has_bias ? bias[oc] : 0.0f;

    int di = do_ * sd - pd;   // depth input coordinate (kernel extent is 1)
    if (di >= 0 && di < D) {
        for (int ic = 0; ic < IC; ++ic) {
            #pragma unroll
            for (int kh = 0; kh < K; ++kh) {
                int hi = ho * sh - ph + kh * dh;
                if (hi < 0 || hi >= H) continue;
                #pragma unroll
                for (int kw = 0; kw < K; ++kw) {
                    int wi = wo * sw - pw + kw * dw;
                    if (wi < 0 || wi >= W) continue;
                    long long xoff = ((((long long)n * IC + ic) * H + hi) * W + wi) * D + di;
                    int woff = (((oc * IC + ic) * K + kh) * K + kw);
                    sum = fmaf(x[xoff], w[woff], sum);
                }
            }
        }
    }
    out[idx] = sum;
}

// Generic fallback for arbitrary K (runtime loop bounds).
__global__ void conv3d_kk1_kernel_generic(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N, int IC, int H, int W, int D,
    int OC, int HO, int WO, int DO,
    int sh, int sw, int sd,
    int ph, int pw, int pd,
    int dh, int dw,
    int K,
    bool has_bias)
{
    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long total = (long long)N * OC * HO * WO * DO;
    if (idx >= total) return;

    int do_ = idx % DO;
    long long t = idx / DO;
    int wo = t % WO; t /= WO;
    int ho = t % HO; t /= HO;
    int oc = t % OC;
    int n  = (int)(t / OC);

    float sum = has_bias ? bias[oc] : 0.0f;

    int di = do_ * sd - pd;
    if (di >= 0 && di < D) {
        for (int ic = 0; ic < IC; ++ic) {
            for (int kh = 0; kh < K; ++kh) {
                int hi = ho * sh - ph + kh * dh;
                if (hi < 0 || hi >= H) continue;
                for (int kw = 0; kw < K; ++kw) {
                    int wi = wo * sw - pw + kw * dw;
                    if (wi < 0 || wi >= W) continue;
                    long long xoff = ((((long long)n * IC + ic) * H + hi) * W + wi) * D + di;
                    int woff = (((oc * IC + ic) * K + kh) * K + kw);
                    sum = fmaf(x[xoff], w[woff], sum);
                }
            }
        }
    }
    out[idx] = sum;
}

torch::Tensor conv3d_forward(
    torch::Tensor x,
    torch::Tensor w,
    torch::Tensor bias,
    int64_t sh, int64_t sw,
    int64_t ph, int64_t pw,
    int64_t dh, int64_t dw,
    int64_t sd, int64_t pd)
{
    TORCH_CHECK(x.is_cuda() && w.is_cuda(), "conv3d_forward: inputs must be CUDA tensors");
    TORCH_CHECK(x.dim() == 5 && w.dim() == 5, "conv3d_forward: bad tensor ranks");
    TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
                "conv3d_forward: only float32 is supported");

    auto xc = x.contiguous();
    auto wc = w.contiguous();

    int N  = (int)xc.size(0);
    int IC = (int)xc.size(1);
    int H  = (int)xc.size(2);
    int W  = (int)xc.size(3);
    int D  = (int)xc.size(4);

    int OC = (int)wc.size(0);
    int K  = (int)wc.size(2);
    TORCH_CHECK((int)wc.size(1) == IC, "conv3d_forward: only groups=1 is supported");
    TORCH_CHECK((int)wc.size(3) == K && (int)wc.size(4) == 1,
                "conv3d_forward: weight must have shape (OC, IC, K, K, 1)");

    int HO = (int)((H + 2 * ph - dh * (K - 1) - 1) / sh + 1);
    int WO = (int)((W + 2 * pw - dw * (K - 1) - 1) / sw + 1);
    int DO = (int)((D + 2 * pd - 1) / sd + 1);   // kernel extent over depth is 1
    TORCH_CHECK(HO > 0 && WO > 0 && DO > 0, "conv3d_forward: invalid output shape");

    auto out = torch::empty({N, OC, HO, WO, DO}, xc.options());
    long long total = (long long)N * OC * HO * WO * DO;
    if (total == 0) return out;

    torch::Tensor bc;
    const float* bptr = nullptr;
    bool has_bias = bias.defined() && bias.numel() > 0;
    if (has_bias) {
        TORCH_CHECK(bias.numel() == OC, "conv3d_forward: bad bias size");
        bc = bias.contiguous();
        bptr = bc.data_ptr<float>();
    }

    const float* xp = xc.data_ptr<float>();
    const float* wp = wc.data_ptr<float>();
    float* op = out.data_ptr<float>();

    int threads = 256;
    long long blocks = (total + threads - 1) / threads;
    auto stream = at::cuda::getCurrentCUDAStream();

    if (K == 3) {
        conv3d_kk1_kernel<3><<<(unsigned)blocks, threads, 0, stream>>>(
            xp, wp, bptr, op, N, IC, H, W, D, OC, HO, WO, DO,
            (int)sh, (int)sw, (int)sd, (int)ph, (int)pw, (int)pd,
            (int)dh, (int)dw, has_bias);
    } else if (K == 1) {
        conv3d_kk1_kernel<1><<<(unsigned)blocks, threads, 0, stream>>>(
            xp, wp, bptr, op, N, IC, H, W, D, OC, HO, WO, DO,
            (int)sh, (int)sw, (int)sd, (int)ph, (int)pw, (int)pd,
            (int)dh, (int)dw, has_bias);
    } else if (K == 5) {
        conv3d_kk1_kernel<5><<<(unsigned)blocks, threads, 0, stream>>>(
            xp, wp, bptr, op, N, IC, H, W, D, OC, HO, WO, DO,
            (int)sh, (int)sw, (int)sd, (int)ph, (int)pw, (int)pd,
            (int)dh, (int)dw, has_bias);
    } else {
        conv3d_kk1_kernel_generic<<<(unsigned)blocks, threads, 0, stream>>>(
            xp, wp, bptr, op, N, IC, H, W, D, OC, HO, WO, DO,
            (int)sh, (int)sw, (int)sd, (int)ph, (int)pw, (int)pd,
            (int)dh, (int)dw, K, has_bias);
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
"""

_cpp_src = r"""
torch::Tensor conv3d_forward(
    torch::Tensor x,
    torch::Tensor w,
    torch::Tensor bias,
    int64_t sh, int64_t sw,
    int64_t ph, int64_t pw,
    int64_t dh, int64_t dw,
    int64_t sd, int64_t pd);
"""

_ext = load_inline(
    name="conv3d_kk1_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv3d_forward"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    3D convolution with an asymmetric (kernel_size, kernel_size, 1) kernel,
    implemented with a single custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Keep an nn.Conv3d submodule purely as the parameter holder so that
        # initialization and state_dict keys exactly match the reference model.
        self.conv3d = nn.Conv3d(
            in_channels, out_channels, (kernel_size, kernel_size, 1),
            stride=stride, padding=padding, dilation=dilation,
            groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        w = self.conv3d.weight
        # Fall back to the reference op for configurations the custom
        # kernel does not cover (non-CUDA, non-float32, or grouped conv).
        if (not x.is_cuda) or x.dtype != torch.float32 or self.conv3d.groups != 1:
            return self.conv3d(x)

        b = self.conv3d.bias
        if b is None:
            b = torch.empty(0, device=x.device, dtype=w.dtype)

        s = self.conv3d.stride
        p = self.conv3d.padding
        d = self.conv3d.dilation
        return _ext.conv3d_forward(
            x, w, b,
            s[0], s[1],      # stride over spatial dims 2 and 3
            p[0], p[1],      # padding over spatial dims 2 and 3
            d[0], d[1],      # dilation over spatial dims 2 and 3
            s[2], p[2])      # stride/padding over the depth dim

